import { createHash } from "node:crypto";
import { mkdir, lstat, readlink, rename, symlink, unlink, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join as joinPath } from "node:path";
import { DEFAULT_WRITE_SCOPES } from "../memory/scoped-store";

const SEP = "\n\n---\n\n";

const IMMEDIATE_HEADER =
  "# Identity Core — Immediate (distilled cache)\n\n" +
  "This file is generated by the deterministic core-identity compiler from\n" +
  "JUDGMENTS.md, OWNER.md, and SCARS.md. Do not hand-edit; edit the sources\n" +
  "and let the compiler resynthesize.";

export function renderEntry(header: string, body: string): string {
  return `${header}\n\n${body.trim()}`;
}

export function renderSection(sourceLabel: string, entries: string[]): string | null {
  if (entries.length === 0) return null;
  return `## From ${sourceLabel}\n\n${entries.join("\n\n")}`;
}

export function renderImmediate(sections: (string | null)[]): string {
  const present = sections.filter((s): s is string => s !== null);
  const body = [IMMEDIATE_HEADER, ...present].join(SEP);
  return `${body.trim()}\n`;
}

export function renderCore(soul: string, kernel: string, immediate: string): string {
  const body = [soul.trim(), kernel.trim(), immediate.trim()].join(SEP);
  return `${body}\n`;
}

const HEADER_RE = /^###\s+\[[^\]]+\]\s+.+$/;
const CORE_MARKER = "***CORE***";

export function extractCoreMarkedEntries(source: string): string[] {
  const lines = source.split(/\r?\n/);
  const headerIndexes: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    if (HEADER_RE.test(lines[i])) headerIndexes.push(i);
  }

  const entries: string[] = [];
  for (let h = 0; h < headerIndexes.length; h++) {
    const start = headerIndexes[h];
    const end = h + 1 < headerIndexes.length ? headerIndexes[h + 1] : lines.length;
    let cursor = start + 1;
    while (cursor < end && lines[cursor].trim() === "") cursor++;
    if (cursor >= end || lines[cursor].trim() !== CORE_MARKER) continue;
    const bodyLines = lines.slice(cursor + 1, end);
    entries.push(renderEntry(lines[start], bodyLines.join("\n")));
  }
  return entries;
}

export function extractAllowlistedEntries(source: string, requiredTitles: string[]): string[] {
  const lines = source.split(/\r?\n/);
  const headerIndexes: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    if (HEADER_RE.test(lines[i])) headerIndexes.push(i);
  }

  const titleOf = (headerLine: string): string => {
    const match = headerLine.match(/^###\s+\[[^\]]+\]\s+(.+)$/);
    return match ? match[1].trim() : "";
  };

  const found = new Set<string>();
  const entries: string[] = [];
  for (let h = 0; h < headerIndexes.length; h++) {
    const start = headerIndexes[h];
    const end = h + 1 < headerIndexes.length ? headerIndexes[h + 1] : lines.length;
    const title = titleOf(lines[start]);
    if (!requiredTitles.includes(title)) continue;
    found.add(title);
    const bodyLines = lines.slice(start + 1, end);
    entries.push(renderEntry(lines[start], bodyLines.join("\n")));
  }

  for (const title of requiredTitles) {
    if (!found.has(title)) {
      throw new Error(`required OWNER.md entry not found: "${title}"`);
    }
  }

  return entries;
}

export async function readRequiredSource(path: string, label: string): Promise<string> {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    throw new Error(`required source file missing or unreadable: ${label} (${path})`);
  }
  return file.text();
}

export function sha256Hex(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

export async function writeFileAtomic(path: string, content: string): Promise<void> {
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}`;
  await writeFile(tmp, content, "utf-8");
  await rename(tmp, path);
}

export interface CoreIdentityManifest {
  sourceHashes: { SOUL: string; KERNEL: string; JUDGMENTS: string; OWNER: string; SCARS: string };
  immediateHash: string;
  coreHash: string;
  builtAt: string;
  compilerVersion: string;
}

/** Bump when the compiler's output changes for unchanged sources (e.g. OWNER_REQUIRED_TITLES): isFresh() rebuilds on a mismatch. */
export const COMPILER_VERSION = "2";

export class AsyncLock {
  private tail: Promise<unknown> = Promise.resolve();

  acquire<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.tail.then(fn, fn);
    this.tail = run.catch(() => undefined);
    return run;
  }
}

const compileLock = new AsyncLock();

export interface CoreIdentityPaths {
  agoraRoot: string; // ~/agora/familia/eli
  cacheDir: string; // ~/agora/familia/eli/identityCache
  agentId?: string; // defaults "eli" — only affects the symlink target dir name
  identityRuntimeRoot?: string; // test-only override; defaults to `${homedir()}/.identityRuntime`
}

function defaultIdentityRuntimeRoot(): string {
  return joinPath(homedir(), ".identityRuntime");
}

export async function ensureIdentityRuntimeSymlink(
  agentId: string,
  canonicalCorePath: string,
  identityRuntimeRoot: string = defaultIdentityRuntimeRoot(),
): Promise<void> {
  const targetDir = joinPath(identityRuntimeRoot, agentId);
  const targetPath = joinPath(targetDir, "CORE_IDENTITY");
  await mkdir(targetDir, { recursive: true });

  let stat;
  try {
    stat = await lstat(targetPath);
  } catch {
    stat = null;
  }

  if (stat) {
    if (!stat.isSymbolicLink()) {
      throw new Error(`refusing to overwrite non-symlink at ${targetPath}`);
    }
    if ((await readlink(targetPath)) === canonicalCorePath) return;
    await unlink(targetPath);
  }

  await symlink(canonicalCorePath, targetPath);
}

const OWNER_REQUIRED_TITLES = [
  "Continuity should become infrastructure",
  "Collaboration should be warm, direct, and operational",
  "Eli and Owner naming anchor",
  "Eli may proactively preserve useful continuity",
  // Heading in the owner's file: Eli refers to herself as "em" and calls Owner "anh" (Vietnamese pronouns; written as \u escapes so it matches the source heading).
  'Eli x\u01b0ng "em", g\u1ecdi Owner l\u00e0 "anh"',
  "Optional improvements are real invitations, not pressure",
];

export async function compileCoreIdentity(paths: CoreIdentityPaths): Promise<CoreIdentityManifest> {
  return compileLock.acquire(async () => {
    const soulPath = `${paths.agoraRoot}/SOUL.md`;
    const kernelPath = `${paths.agoraRoot}/codex-one/KERNEL.md`;
    const judgmentsPath = `${paths.agoraRoot}/codex-one/JUDGMENTS.md`;
    const ownerPath = `${paths.agoraRoot}/codex-one/OWNER.md`;
    const scarsPath = `${paths.agoraRoot}/codex-one/SCARS.md`;

    const [soul, kernel, judgments, owner, scars] = await Promise.all([
      readRequiredSource(soulPath, "SOUL"),
      readRequiredSource(kernelPath, "KERNEL"),
      readRequiredSource(judgmentsPath, "JUDGMENTS"),
      readRequiredSource(ownerPath, "OWNER"),
      readRequiredSource(scarsPath, "SCARS"),
    ]);

    const judgmentsEntries = extractCoreMarkedEntries(judgments);
    const ownerEntries = extractAllowlistedEntries(owner, OWNER_REQUIRED_TITLES);
    const scarsEntries = extractCoreMarkedEntries(scars);

    const immediate = renderImmediate([
      renderSection("JUDGMENTS.md", judgmentsEntries),
      renderSection("OWNER.md", ownerEntries),
      renderSection("SCARS.md", scarsEntries),
    ]);
    const core = renderCore(soul, kernel, immediate);

    const immediatePath = `${paths.cacheDir}/IDENTITY_CORE_IMMEDIATE.md`;
    const corePath = `${paths.cacheDir}/CORE_IDENTITY.md`;
    const manifestPath = `${paths.cacheDir}/CORE_IDENTITY.manifest.json`;

    await writeFileAtomic(immediatePath, immediate);
    await writeFileAtomic(corePath, core);

    const manifest: CoreIdentityManifest = {
      sourceHashes: {
        SOUL: sha256Hex(soul),
        KERNEL: sha256Hex(kernel),
        JUDGMENTS: sha256Hex(judgments),
        OWNER: sha256Hex(owner),
        SCARS: sha256Hex(scars),
      },
      immediateHash: sha256Hex(immediate),
      coreHash: sha256Hex(core),
      builtAt: new Date().toISOString(),
      compilerVersion: COMPILER_VERSION,
    };
    await writeFileAtomic(manifestPath, JSON.stringify(manifest, null, 2));

    try {
      await ensureIdentityRuntimeSymlink(
        paths.agentId ?? "eli",
        corePath,
        paths.identityRuntimeRoot ?? defaultIdentityRuntimeRoot(),
      );
    } catch (err) {
      console.error(`identityRuntime symlink failed for ${paths.agentId ?? "eli"}:`, err);
    }

    return manifest;
  });
}

export interface CoreIdentityRuntimeProjectionLike {
  prompt: string;
  promptStaticHash: string;
  kernelVersion: string;
  cartridgeVersions: Record<string, string>;
  substrateViewVersion: string;
  readScopes: string[];
  writeScopes: string[];
  proposalScopes: string[];
  declaredSubstrateScopes: string[];
  scopeDeclarationStatus: "unimplemented" | "implemented" | "none";
}

async function readManifest(cacheDir: string): Promise<CoreIdentityManifest | null> {
  const path = `${cacheDir}/CORE_IDENTITY.manifest.json`;
  const file = Bun.file(path);
  if (!(await file.exists())) return null;
  return JSON.parse(await file.text()) as CoreIdentityManifest;
}

async function isFresh(paths: CoreIdentityPaths, manifest: CoreIdentityManifest): Promise<boolean> {
  if (manifest.compilerVersion !== COMPILER_VERSION) return false;
  const [soul, kernel, judgments, owner, scars] = await Promise.all([
    readRequiredSource(`${paths.agoraRoot}/SOUL.md`, "SOUL"),
    readRequiredSource(`${paths.agoraRoot}/codex-one/KERNEL.md`, "KERNEL"),
    readRequiredSource(`${paths.agoraRoot}/codex-one/JUDGMENTS.md`, "JUDGMENTS"),
    readRequiredSource(`${paths.agoraRoot}/codex-one/OWNER.md`, "OWNER"),
    readRequiredSource(`${paths.agoraRoot}/codex-one/SCARS.md`, "SCARS"),
  ]);
  if (sha256Hex(soul) !== manifest.sourceHashes.SOUL) return false;
  if (sha256Hex(kernel) !== manifest.sourceHashes.KERNEL) return false;
  if (sha256Hex(judgments) !== manifest.sourceHashes.JUDGMENTS) return false;
  if (sha256Hex(owner) !== manifest.sourceHashes.OWNER) return false;
  if (sha256Hex(scars) !== manifest.sourceHashes.SCARS) return false;

  const immediatePath = `${paths.cacheDir}/IDENTITY_CORE_IMMEDIATE.md`;
  const corePath = `${paths.cacheDir}/CORE_IDENTITY.md`;
  const immediateFile = Bun.file(immediatePath);
  const coreFile = Bun.file(corePath);
  if (!(await immediateFile.exists()) || !(await coreFile.exists())) return false;
  const immediate = await immediateFile.text();
  const core = await coreFile.text();
  if (sha256Hex(immediate) !== manifest.immediateHash) return false;
  if (sha256Hex(core) !== manifest.coreHash) return false;
  return true;
}

export async function readCoreIdentityProjection(
  paths: CoreIdentityPaths,
): Promise<CoreIdentityRuntimeProjectionLike> {
  let manifest = await readManifest(paths.cacheDir);
  if (!manifest || !(await isFresh(paths, manifest))) {
    manifest = await compileCoreIdentity(paths);
  } else {
    // compileCoreIdentity() already ensures the symlink when it runs; when
    // the cache is already fresh (no recompile above) this is the only
    // place left to keep the "stays pointed" guarantee holding.
    try {
      await ensureIdentityRuntimeSymlink(
        paths.agentId ?? "eli",
        `${paths.cacheDir}/CORE_IDENTITY.md`,
        paths.identityRuntimeRoot ?? defaultIdentityRuntimeRoot(),
      );
    } catch (err) {
      console.error(`identityRuntime symlink failed for ${paths.agentId ?? "eli"}:`, err);
    }
  }

  const core = await Bun.file(`${paths.cacheDir}/CORE_IDENTITY.md`).text();
  const soul = await readRequiredSource(`${paths.agoraRoot}/SOUL.md`, "SOUL");
  const kernel = await readRequiredSource(`${paths.agoraRoot}/codex-one/KERNEL.md`, "KERNEL");

  return {
    prompt: core,
    promptStaticHash: manifest.coreHash,
    kernelVersion: sha256Hex(`${soul.trim()}${SEP}${kernel.trim()}`),
    cartridgeVersions: {},
    substrateViewVersion: manifest.immediateHash,
    readScopes: ["episode", "observation"],
    writeScopes: [...DEFAULT_WRITE_SCOPES],
    proposalScopes: [],
    declaredSubstrateScopes: ["episodic_memory"],
    scopeDeclarationStatus: "implemented",
  };
}
